% Gloria agent marciano (generated by playground/mkpage.py).
% Do not edit: regenerate from src/agents/marciano/ instead.
:- module(marciano, []).

%% %%%%%%%%%%%%%%%%%%%%%%%%%%%%%% marciano.kb
% marciano.kb -- metas (if_/2) y creencias (def/2)
%
% Spec (espanol):
%   Ud es un robot explorador enviado a Marte en busca de rastros de vida
%   marciana.  El terreno es una cuadricula de cuadrados unitarios: cada
%   cuadrado se identifica con coordenadas (E,N), donde E crece hacia el
%   Este y N hacia el Norte desde el origen.  Ud comienza en (0,0) mirando
%   al Este y avanza exactamente un cuadrado por paso.
%
%   Ud conoce su posicion y orientacion actuales, y usa aritmetica simple
%   para calcular las coordenadas del cuadrado de adelante y del cuadrado a
%   la derecha.  Cada vez que pasa a un cuadrado nuevo registra su
%   observacion en un mapa; para saber si ya estuvo alli consulta ese mapa.
%
%   Sistema de produccion con memoria (reglas, en orden de prioridad):
%     1. Si el cuadrado de adelante esta frente_libre y ya lo visite,
%        entonces volteo a la derecha.
%     2. Si el cuadrado de adelante esta frente_libre y no lo he visitado,
%        entonces avanzo a el (y registro la visita).
%     3. Si el cuadrado de adelante tiene un obstaculo_al_frente sin vida,
%        entonces volteo a la derecha.
%     4. Si el cuadrado de adelante tiene vida,
%        entonces reporto sus coordenadas al centro de control y volteo a
%        la derecha.
%
% Nota de codificacion:
%   * `posicion/2` y `orientacion/1` las reporta el cuerpo en cada paso.
%     El agente calcula `adelante/5` con aritmetica (ver marciano.main).
%   * La memoria es el conjunto de hechos `recuerda(mapa((E,N),Estado))` y
%     `recuerda(visitado((E,N)))`; se consulta con `visitado/1`,
%     `no_visitado/1` y se actualiza con `registra_visita/1` y
%     `registra_observacion/2`.
%   * La regla "ya lo visite" va ANTES de la regla "no lo visite": el motor
%     evalua en orden de fuente y la primera regla que se satisface gana.
%     Asi, al llegar a un cuadrado nuevo solo dispara `avanzar` (que ademas
%     lo marca visitado) y no `voltear_derecha`.
%   * `frente_libre`, `obstaculo_al_frente` y `vida` son observaciones mutuamente excluyentes.

% ---------------------------------------------------------------- metas
% 1. El cuadrado de adelante esta frente_libre pero ya lo visite: volteo a la
%    derecha.
if_((posicion(E, N), orientacion(D), frente_libre,
     adelante(E, N, D, E2, N2), visitado((E2, N2))),
    [voltear_derecha]).

% 2. El cuadrado de adelante esta frente_libre y es nuevo: avanzo y registro la
%    visita.
if_((posicion(E, N), orientacion(D), frente_libre,
     adelante(E, N, D, E2, N2), no_visitado((E2, N2)),
     registra_visita((E2, N2))),
    [avanzar]).

% 3. Hay un obstaculo_al_frente sin vida adelante: lo registro y volteo a la derecha.
if_((posicion(E, N), orientacion(D), obstaculo_al_frente,
     adelante(E, N, D, E2, N2),
     registra_observacion((E2, N2), obstaculo_al_frente)),
    [voltear_derecha]).

% 4. Hay vida adelante: reporto sus coordenadas al centro de control y
%    volteo a la derecha.
if_((posicion(E, N), orientacion(D), vida,
     adelante(E, N, D, E2, N2),
     registra_observacion((E2, N2), vida)),
    [reportar((E2, N2)), voltear_derecha]).

%% %%%%%%%%%%%%%%%%%%%%%%%%%%%%%% marciano.main
tracefile('marciano.dot').  % see flach/graphviz.pl
for_testing_only(false).

% abducible predicates
%
% Sensations.  The body reports the robot's current square and heading, and
% the life-recognition module reports what it sees in the square directly
% ahead: `frente_libre`, `obstaculo_al_frente` (an obstacle without life) or `vida` (an
% obstacle with signs of life).
abd(posicion).
abd(orientacion).
abd(frente_libre).
abd(obstaculo_al_frente).
abd(vida).

% Actions the robot can perform.
abd(avanzar).
abd(voltear_derecha).
abd(reportar).

% observable predicates
%
observable(posicion(_,_)).
observable(orientacion(_)).
observable(frente_libre).
observable(obstaculo_al_frente).
observable(vida).

% built-in, user-defined predicates: coordinates, orientation and map memory
%
% The terrain is a grid of unit squares.  Square (0,0) is the origin; E grows
% to the East and N to the North.  The robot starts at (0,0) facing East and
% moves one square per step.
%
%   adelante(E,N,D,E2,N2) -- coordinates of the square ahead
%   derecha(E,N,D,E2,N2)  -- coordinates of the square to the right
%   visitado(P)           -- P is a square the robot has occupied
%   no_visitado(P)        -- P is not in the visited set
%   registra_visita(P)    -- mark P visited and record it as free
%   registra_observacion(P, Estado) -- record Estado for P in the map
user_built(adelante(_,_,_,_,_)).
user_built(derecha(_,_,_,_,_)).
user_built(visitado(_)).
user_built(no_visitado(_)).
user_built(registra_visita(_)).
user_built(registra_observacion(_,_)).

% ---------------------------------------------------------------- initial map
% The robot starts at the origin, which is free and already visited.  Keeping
% this as a `visitado/1` fact (instead of a `recuerda/1` fact) lets the same
% .main work both when it is consulted into `user` (MCP server) and when it is
% asserted into the agent module (web server): `recuerda/1` always refers to
% the engine's working-memory store.
visitado((0,0)).

% ------------------------------------------------------ coordinate arithmetic
% Coordinates of the square directly ahead, given the current square and the
% heading.
adelante(E, N, este,  E2, N)  :- E2 is E + 1.
adelante(E, N, norte, E,  N2) :- N2 is N + 1.
adelante(E, N, oeste, E2, N)  :- E2 is E - 1.
adelante(E, N, sur,   E,  N2) :- N2 is N - 1.

% Coordinates of the square to the right: the square that becomes "ahead"
% after turning right.
derecha(E, N, este,  E,  N2) :- N2 is N - 1.
derecha(E, N, sur,   E2, N)  :- E2 is E - 1.
derecha(E, N, oeste, E,  N2) :- N2 is N + 1.
derecha(E, N, norte, E2, N)  :- E2 is E + 1.

% ------------------------------------------------------------- map memory
visitado(P) :-
    recuerda(visitado(P)).

no_visitado(P) :-
    not(visitado(P)).

% Record a square the robot has just moved into.  The square is free because
% the robot occupies it.
registra_visita(P) :-
    memoriza(visitado(P)),
    registra_mapa(P, frente_libre).

% Record what the robot saw in a square (obstacle or life).
registra_observacion(P, Estado) :-
    registra_mapa(P, Estado).

% Keep the first observation of a square (the world is static).
registra_mapa(P, _Estado) :-
    recuerda(mapa(P, _)).
registra_mapa(P, Estado) :-
    not(recuerda(mapa(P, _))),
    memoriza(mapa(P, Estado)).
